import { Group, Mesh, BoxGeometry, OctahedronGeometry, PlaneGeometry, PointLight, Color } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { positionLocal, length, smoothstep, vec3, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'ornamental-divider';

  const disposables = [];
  const timelines = [];

  // --- machined rule (thin bar, catches light like brushed metal) ---
  const RULE_LENGTH = 2.6;
  const ruleGeo = new BoxGeometry(RULE_LENGTH, 0.03, 0.03);
  const ruleMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.paper),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ink-toned end caps for weight
  const capGeo = new BoxGeometry(0.08, 0.06, 0.06);
  const capMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.4,
    roughness: 0.6,
    clearcoat: 0.15,
  });
  const capLeft = new Mesh(capGeo, capMat);
  capLeft.position.x = -RULE_LENGTH / 2;
  const capRight = new Mesh(capGeo, capMat);
  capRight.position.x = RULE_LENGTH / 2;
  root.add(capLeft, capRight);
  disposables.push(capGeo, capMat);

  // --- center jewel: the ONE brightest element on this node ---
  const jewelGeo = new OctahedronGeometry(0.13, 0);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 2.0,
    metalness: 0.3,
    roughness: 0.28,
    clearcoat: 0.25,
    clearcoatRoughness: 0.2,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.rotation.y = Math.PI / 8;
  root.add(jewel);
  disposables.push(jewelGeo, jewelMat);

  // local accent rim light seated at the jewel, kept within intensity ceiling
  const rimLight = new PointLight(new Color(colors.accent), 1.1, 2.2, 2.0);
  rimLight.position.set(0, 0.15, 0.35);
  root.add(rimLight);

  // --- contact shadow beneath the divider (radial falloff via TSL) ---
  const shadowGeo = new PlaneGeometry(1.4, 0.6, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const dist = length(positionLocal.xy.mul(vec3(1.0, 1.6, 1.0).xy));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(float(0.75), float(0.0), dist).mul(0.45);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -0.22;
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // --- optional decorative flourish loaded from the shared mesh asset ---
  let glbScene = null;
  if (config.meshUrl) {
    ctx.glbLoader
      .loadGLB(config.meshUrl)
      .then((gltf) => {
        if (root.userData.destroyed) return;
        glbScene = gltf.scene;
        glbScene.scale.setScalar(0.06);
        glbScene.position.set(0, 0.02, -0.05);
        glbScene.traverse((child) => {
          if (child.isMesh) {
            child.castShadow = false;
            child.receiveShadow = false;
          }
        });
        root.add(glbScene);
      })
      .catch(() => {
        /* silent fallback — procedural rule + jewel already carry the design */
      });
  }

  // --- motion state ---
  const baseY = 0;
  const baseScale = 1;
  root.scale.setScalar(baseScale);
  root.position.y = baseY;

  let hoverTl = null;
  let pressTl = null;

  function onPointerEnter() {
    if (pressTl) return;
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: baseY + 0.15, duration: 0.5, ease: 'power3.out' }, 0);
    hoverTl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' }, 0);
    hoverTl.to(jewelMat, { emissiveIntensity: 2.3, duration: 0.4, ease: 'power2.out' }, 0);
    timelines.push(hoverTl);
  }

  function onPointerLeave() {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: baseY, duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
    hoverTl.to(jewelMat, { emissiveIntensity: 2.0, duration: 0.4, ease: 'power2.out' }, 0);
    timelines.push(hoverTl);
  }

  function onClick() {
    pressTl?.kill();
    pressTl = gsap.timeline({
      onComplete: () => {
        pressTl = null;
      },
    });
    pressTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(root.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: 'power2.out' });
    timelines.push(pressTl);
    ctx.emit('hub-home.select', { nodeId: config.id ?? 'home-divider' });
  }

  root.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerover: onPointerEnter,
    pointerleave: onPointerLeave,
    pointerout: onPointerLeave,
    click: onClick,
  };

  root.userData.cleanup = () => {
    root.userData.destroyed = true;
    timelines.forEach((tl) => tl.kill());
    hoverTl?.kill();
    pressTl?.kill();

    root.remove(rimLight);

    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });

    if (glbScene) {
      glbScene.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose();
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => m?.dispose());
        }
      });
      root.remove(glbScene);
    }
  };

  return root;
}
